"""Studio session-token verification for the model service.

Endpoint and socket code depend only on the ``TokenVerifier`` protocol.

Concurrency contract: the in-memory cache and single-flight map are safe only
because the service runs single-process (``model_service.py`` uses
``app.run(..., legacy=True)`` with the default single worker — the same
contract the module-global ``running_bots``/``trainings`` state relies on).

Never log a token or its hash at any level.
"""

import asyncio
import hashlib
import re
import time
from collections import OrderedDict
from dataclasses import dataclass
from datetime import datetime
from http import HTTPStatus
from typing import Any, Callable, Dict, Literal, Optional, Protocol, Tuple

import aiohttp
import structlog

from rasa.model_manager import studio_jwt_auth
from rasa.shared.exceptions import RasaException

structlogger = structlog.get_logger()


class AuthenticationError(RasaException):
    """The token was definitively rejected. Maps to HTTP 401."""


class AuthUnavailableError(RasaException):
    """Verification could not be performed. Maps to HTTP 503. Never cached."""


class UpstreamUnreachableError(AuthUnavailableError):
    """Studio could not be reached, or is shedding load (timeout, 429, 5xx)."""


@dataclass(frozen=True)
class AuthenticatedUser:
    """The only session facts ever cached or attached to a request."""

    id: str
    role: Optional[str]
    global_permissions: Tuple[str, ...]
    expires_at: float
    """Session expiry as epoch seconds."""


class TokenVerifier(Protocol):
    """Verification seam. Endpoint and socket code only see this protocol."""

    async def verify(self, token: str) -> AuthenticatedUser:
        """Return the session's user, or raise a typed auth error."""
        ...

    async def close(self) -> None:
        """Release any held resources (HTTP sessions)."""
        ...


# better-auth session tokens are short URL-safe strings. Anything outside this
# shape cannot be a valid token, so it is rejected locally without spending
# Studio's per-IP introspection rate-limit budget on it.
_PLAUSIBLE_TOKEN_SHAPE = re.compile(r"^[A-Za-z0-9._~+/=-]{16,512}\Z")

GET_SESSION_PATH = "/api/auth/get-session?disableRefresh=true"
INTROSPECTION_TIMEOUT = aiohttp.ClientTimeout(total=3, sock_connect=1)
MAX_CONCURRENT_INTROSPECTIONS = 8

POSITIVE_CACHE_TTL_SECONDS = 30.0
POSITIVE_CACHE_MAX_ENTRIES = 1024
STALE_GRACE_SECONDS = 120.0
UNAVAILABLE_LATCH_SECONDS = 1.5


def is_plausible_session_token(token: str) -> bool:
    """Cheap local pre-check rejecting structurally-impossible bearer values."""
    return bool(_PLAUSIBLE_TOKEN_SHAPE.match(token))


def parse_session_payload(payload: Dict[str, Any]) -> AuthenticatedUser:
    """Map a better-auth ``get-session`` body onto ``AuthenticatedUser``.

    Raises ``ValueError`` on schema mismatch — callers treat that as an
    upstream fault (503), never as a rejection. A ``null`` role is a valid
    session (Studio's ``customSession`` can derive a null role).
    """
    user = payload.get("user")
    session = payload.get("session")
    if not isinstance(user, dict) or not isinstance(session, dict):
        raise ValueError("Expected 'user' and 'session' objects in response.")

    user_id = user.get("id")
    if not isinstance(user_id, str) or not user_id:
        raise ValueError("Expected a non-empty string 'user.id'.")

    role = user.get("role")
    if role is not None and not isinstance(role, str):
        raise ValueError("Expected 'user.role' to be a string or null.")

    permissions = user.get("globalPermissions")
    if permissions is None:
        permissions = []
    if not isinstance(permissions, list) or not all(
        isinstance(permission, str) for permission in permissions
    ):
        raise ValueError("Expected 'user.globalPermissions' to be a list of strings.")

    return AuthenticatedUser(
        id=user_id,
        role=role,
        global_permissions=tuple(permissions),
        expires_at=_parse_expires_at(session.get("expiresAt")),
    )


def _parse_expires_at(value: Any) -> float:
    if not isinstance(value, str):
        raise ValueError("Expected 'session.expiresAt' to be an ISO date string.")
    # Python 3.10's fromisoformat can't parse a trailing "Z".
    normalized = value.replace("Z", "+00:00")
    try:
        return datetime.fromisoformat(normalized).timestamp()
    except ValueError as error:
        raise ValueError("Could not parse 'session.expiresAt'.") from error


@dataclass
class _CacheEntry:
    user: AuthenticatedUser
    fresh_until: float
    """Monotonic deadline for serving without re-introspection."""
    stale_until: float
    """Monotonic deadline for serving during upstream unavailability only."""


class SessionIntrospectionVerifier:
    """Verifies session tokens by introspecting Studio's better-auth backend.

    Response classification (spec SWI-1437):
      - 200 with a valid session schema -> authenticated
      - 200 with body ``null``          -> AuthenticationError (401)
      - timeout / connection failure / 429 / 5xx -> UpstreamUnreachableError
        (503), never cached, arms the unavailability latch
      - redirect / other non-200 / malformed JSON / non-JSON content type /
        schema mismatch                 -> AuthUnavailableError (503), never
        cached, latch untouched
    """

    def __init__(
        self,
        studio_auth_url: str,
        monotonic_clock: Callable[[], float] = time.monotonic,
        wall_clock: Callable[[], float] = time.time,
    ) -> None:
        self._get_session_url = f"{studio_auth_url.rstrip('/')}{GET_SESSION_PATH}"
        self._monotonic = monotonic_clock
        self._wall = wall_clock
        self._http: Optional[aiohttp.ClientSession] = None
        self._introspection_slots = asyncio.Semaphore(MAX_CONCURRENT_INTROSPECTIONS)
        self._cache: "OrderedDict[str, _CacheEntry]" = OrderedDict()
        self._in_flight: "Dict[str, asyncio.Task[AuthenticatedUser]]" = {}
        self._upstream_unavailable_until = 0.0

    async def verify(self, token: str) -> AuthenticatedUser:
        """Return the session's user or raise a typed auth error."""
        if not is_plausible_session_token(token):
            raise AuthenticationError("Malformed bearer token.")

        token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()

        fresh = self._fresh_cache_entry(token_hash)
        if fresh is not None:
            return fresh.user

        # Shielded so that cancelling one caller leaves the lookup, and the
        # other callers waiting on it, unaffected.
        return await asyncio.shield(self._shared_lookup(token, token_hash))

    async def close(self) -> None:
        """Close the shared HTTP session."""
        if self._http is not None and not self._http.closed:
            await self._http.close()

    def _shared_lookup(
        self, token: str, token_hash: str
    ) -> "asyncio.Task[AuthenticatedUser]":
        """Return the in-flight lookup for this token, starting one if needed.

        It runs as its own task so no caller owns it: whoever arrives first
        starts it, and a caller going away leaves it running for the rest.
        """
        in_flight = self._in_flight.get(token_hash)
        if in_flight is not None:
            return in_flight

        lookup = asyncio.create_task(self._verify_uncached(token, token_hash))
        self._in_flight[token_hash] = lookup
        lookup.add_done_callback(
            lambda finished: self._release_lookup(token_hash, finished)
        )
        return lookup

    def _release_lookup(
        self, token_hash: str, lookup: "asyncio.Task[AuthenticatedUser]"
    ) -> None:
        """Evict a finished lookup and mark its failure as retrieved.

        A lingering entry would pin one result, or one failure, for every later
        request. If every caller was cancelled, nothing retrieves the exception
        and it warns on garbage collection.
        """
        if self._in_flight.get(token_hash) is lookup:
            del self._in_flight[token_hash]
        if not lookup.cancelled():
            lookup.exception()

    async def _verify_uncached(self, token: str, token_hash: str) -> AuthenticatedUser:
        if self._monotonic() < self._upstream_unavailable_until:
            return self._stale_user_or_unavailable(token_hash)

        try:
            user = await self._introspect(token)
        except UpstreamUnreachableError:
            self._upstream_unavailable_until = (
                self._monotonic() + UNAVAILABLE_LATCH_SECONDS
            )
            return self._stale_user_or_unavailable(token_hash)
        except AuthUnavailableError:
            # Not a signal about Studio's load, so the latch stays untouched.
            return self._stale_user_or_unavailable(token_hash)
        except AuthenticationError:
            # Definitive rejection invalidates any stale entry immediately.
            self._cache.pop(token_hash, None)
            raise

        self._cache_positive(token_hash, user)
        return user

    def _fresh_cache_entry(self, token_hash: str) -> Optional[_CacheEntry]:
        entry = self._cache.get(token_hash)
        if entry is None:
            return None
        if self._monotonic() >= entry.fresh_until:
            return None  # kept (not evicted) for the stale-serving window
        if self._wall() >= entry.user.expires_at:
            self._cache.pop(token_hash, None)
            return None
        self._cache.move_to_end(token_hash)
        return entry

    def _stale_user_or_unavailable(self, token_hash: str) -> AuthenticatedUser:
        entry = self._cache.get(token_hash)
        if (
            entry is not None
            and self._monotonic() < entry.stale_until
            and self._wall() < entry.user.expires_at
        ):
            structlogger.warning(
                "model_api.auth.serving_stale_verification",
                user_id=entry.user.id,
                event_info=(
                    "Studio introspection is unavailable; serving a cached "
                    "positive verification within the grace window."
                ),
            )
            return entry.user
        raise AuthUnavailableError("Session introspection is unavailable.")

    def _cache_positive(self, token_hash: str, user: AuthenticatedUser) -> None:
        remaining = user.expires_at - self._wall()
        if remaining <= 0:
            return
        fresh_until = self._monotonic() + min(POSITIVE_CACHE_TTL_SECONDS, remaining)
        self._cache[token_hash] = _CacheEntry(
            user=user,
            fresh_until=fresh_until,
            stale_until=fresh_until + STALE_GRACE_SECONDS,
        )
        self._cache.move_to_end(token_hash)
        while len(self._cache) > POSITIVE_CACHE_MAX_ENTRIES:
            self._cache.popitem(last=False)

    async def _introspect(self, token: str) -> AuthenticatedUser:
        try:
            async with self._introspection_slots:
                async with self._http_session().get(
                    self._get_session_url,
                    headers={"Authorization": f"Bearer {token}"},
                    allow_redirects=False,
                ) as upstream:
                    if upstream.status != HTTPStatus.OK:
                        raise self._unavailable_for_status(upstream.status)
                    payload = await upstream.json()
        except AuthUnavailableError:
            raise
        except aiohttp.ContentTypeError as error:
            raise AuthUnavailableError(
                "Session introspection did not return JSON."
            ) from error
        except ValueError as error:
            # json.JSONDecodeError subclasses ValueError.
            raise AuthUnavailableError(
                "Session introspection returned malformed JSON."
            ) from error
        except (aiohttp.ClientError, asyncio.TimeoutError) as error:
            raise UpstreamUnreachableError("Session introspection failed.") from error

        if payload is None:
            # better-auth returns `200 null` for invalid/expired tokens.
            raise AuthenticationError("No active session for this token.")

        try:
            user = parse_session_payload(payload)
        except ValueError as error:
            raise AuthUnavailableError(
                "Session introspection response did not match the expected schema."
            ) from error

        if user.expires_at <= self._wall():
            raise AuthenticationError("Session is expired.")
        return user

    @staticmethod
    def _unavailable_for_status(status: int) -> AuthUnavailableError:
        """Classify a non-200 introspection status.

        429 and 5xx mean Studio is struggling and further calls should back off.
        Anything else is a deployment or routing fault (wrong URL, redirect to a
        login page) that says nothing about its load.
        """
        message = f"Session introspection returned HTTP {status}."
        if (
            status == HTTPStatus.TOO_MANY_REQUESTS
            or status >= HTTPStatus.INTERNAL_SERVER_ERROR
        ):
            return UpstreamUnreachableError(message)
        return AuthUnavailableError(message)

    def _http_session(self) -> aiohttp.ClientSession:
        # Created lazily so the session binds to the running event loop.
        if self._http is None or self._http.closed:
            self._http = aiohttp.ClientSession(
                timeout=INTROSPECTION_TIMEOUT,
                connector=aiohttp.TCPConnector(limit=MAX_CONCURRENT_INTROSPECTIONS),
            )
        return self._http


class KeycloakTokenVerifier:
    """Pre-SWI-1500 Keycloak socket auth: studio_jwt_auth reused unchanged."""

    async def verify(self, token: str) -> AuthenticatedUser:
        """Return the token's user, or raise a typed auth error."""
        # Key availability is checked first so "Keycloak down" surfaces as
        # AuthUnavailableError (socket `auth_unavailable`, fail closed) — the
        # module folds key-fetch failure and bad tokens into one exception type.
        public_key = await asyncio.to_thread(
            studio_jwt_auth.get_public_key_from_keycloak
        )
        if public_key is None:
            raise AuthUnavailableError("Failed to fetch public key from keycloak.")
        try:
            claims = await asyncio.to_thread(
                studio_jwt_auth.authenticate_user_to_service, token
            )
        except studio_jwt_auth.UserToServiceAuthenticationError as error:
            raise AuthenticationError(error.message) from error
        try:
            return AuthenticatedUser(
                id=claims["sub"],
                role=None,
                global_permissions=(),
                expires_at=claims["exp"],
            )
        except KeyError as error:
            raise AuthenticationError(f"Token is missing claim {error}.") from error

    async def close(self) -> None:
        """Release held resources — none: the module uses per-call requests."""


@dataclass(frozen=True)
class AuthPolicy:
    """Resolved once at startup; the mode never changes at runtime.

    ``rest_verifier=None`` means REST is open — in production only the
    keycloak-legacy branch of ``resolve_auth_policy`` builds that.
    """

    mode: Literal["studio", "keycloak-legacy"]
    rest_verifier: Optional[TokenVerifier]
    socket_verifier: TokenVerifier


def resolve_auth_policy(
    studio_auth_url: Optional[str], keycloak_url: Optional[str]
) -> Optional[AuthPolicy]:
    """Pick the auth mode from deployment configuration, once at startup."""
    if studio_auth_url:
        if keycloak_url:
            structlogger.warning(
                "model_api.auth.keycloak_url_ignored",
                event_info=(
                    "Both STUDIO_AUTH_URL and KEYCLOAK_URL are set. Using "
                    "Studio session auth; KEYCLOAK_URL is ignored."
                ),
            )
        verifier = SessionIntrospectionVerifier(studio_auth_url)
        return AuthPolicy("studio", rest_verifier=verifier, socket_verifier=verifier)

    if keycloak_url:
        structlogger.warning(
            "model_api.auth.keycloak_legacy_mode",
            event_info=(
                "KEYCLOAK_URL is set and STUDIO_AUTH_URL is not: running "
                "in Studio 1.x compatibility mode. Socket connections require "
                "a Keycloak token; REST endpoints are UNAUTHENTICATED in this "
                "mode."
            ),
        )
        return AuthPolicy(
            "keycloak-legacy",
            rest_verifier=None,
            # No constructor args: the restored module reads the env itself.
            socket_verifier=KeycloakTokenVerifier(),
        )

    return None


def policy_from_app(app: Any) -> Optional[AuthPolicy]:
    """Read the app-scoped auth policy installed by the server-start listener."""
    return getattr(app.ctx, "auth_policy", None)
